mapper.select:
SELECT *
FROM base.geo_location
WHERE cont_code = #{contCode}
    AND ctry_code = #{ctryCode}
    AND sub1_code IS NOT DISTINCT FROM #{sub1Code}
    AND sub2_code IS NOT DISTINCT FROM #{sub2Code}
    AND city_name IS NOT DISTINCT FROM #{cityName}
    AND postcode IS NOT DISTINCT FROM #{postcode}
    LIMIT 1
